#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    int globalMax = 0;

    #pragma omp parallel
    {
        int localMax = 0;

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < N; ++i) {
            int deg = 0;
            const std::size_t row = i * N;
            for (std::size_t j = 0; j < N; ++j) {
                deg += A[row + j] != 0; // treat any nonzero as an edge
            }
            if (deg > localMax) localMax = deg;
        }

        #pragma omp critical
        {
            if (localMax > globalMax) globalMax = localMax;
        }
    }

    return globalMax;
}
